import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const MyFlaggedListings = () => {
  const [flagged, setFlagged] = useState([]);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/flagged/user/${userId}`)
      .then((res) => res.json())
      .then((data) => setFlagged(data))
      .catch((err) => console.error("Error fetching flagged listings:", err));
  }, [userId]);

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="dashboard-main">
        <h2 style={{ textAlign: "center", margin: "32px 0" }}>My Flagged Listings</h2>
        <div className="item-grid">
          {flagged.length > 0 ? (
            flagged.map((item) => (
              <div className="item-card" key={item.id}>
                <div className="image-placeholder">
                  {item.image ? <img src={item.image} alt={item.title} /> : <span>No Image</span>}
                </div>
                <h4>{item.title}</h4>
                <p>{item.description}</p>
                <p><strong>Condition:</strong> {item.condition}</p>
                <p><strong>Reason:</strong> {item.reason}</p>
              </div>
            ))
          ) : (
            <p style={{ textAlign: "center" }}>You haven't flagged any listings yet.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default MyFlaggedListings;
